using size_t=decltype(sizeof(0)); using napi_env=void*; using napi_value=const char*; using napi_status=int; const int napi_ok=0; void HILOG_INFO(int,const char*,...);
napi_status napi_get_value_string_utf8(napi_env env,napi_value value,char *buffer,size_t size,size_t *length){*length=(unsigned char)value[0];return napi_ok;}
void Callback(const char *key){size_t length=0;napi_get_value_string_utf8(nullptr,key,nullptr,0,&length);HILOG_INFO(1,"%{public}u",(unsigned)length);}
